  ScrollView scroll=new ScrollView(this);scroll.addView(box);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("采集授权向导").setView(scroll).setPositiveButton("完成",null).create();dialog.setOnDismissListener(d->{guideSummary=null;});dialog.show();
