  for(int i=0;i<Config.TABS.length;i++){final int n=i;LinearLayout cell=column();TextView t=text(Config.TABS[i],12,ACCENT);t.setGravity(Gravity.CENTER);cell.addView(t,new LinearLayout.LayoutParams(dp(i>8?86:60),dp(36)));View line=new View(this);line.setBackgroundColor(i==0?ACCENT:0xFFDCD7E8);cell.addView(line,new LinearLayout.LayoutParams(-1,dp(2)));cell.setOnClickListener(v->{tab=n;if(sampleIndex!=null&&viewport!=null)renderTab();});tabs.addView(cell);}
