  final int sessionToken=sessionGeneration;final CsvIndex oldSamples=sampleIndex,oldFrames=frameIndex;sampleIndex=frameIndex=null;
  historyJob=historyIo.submit(()->{CsvIndex samples=null,frames=null;try{
   closeIndex(oldSamples);closeIndex(oldFrames);boolean active=MonitorService.running&&f.getAbsolutePath().equals(MonitorService.sessionPath);
   JSONObject result=active?SessionAnalysis.read(f):SessionAnalysis.ensure(f,(rows,frameRows)->{if(Thread.currentThread().isInterrupted())throw new CancellationException("已切换会话");ui.post(()->{if(!destroyed&&sessionToken==sessionGeneration)loading.setText("正在从原始数据恢复统计："+rows+" 次采样、"+frameRows+" 条呈现间隔…");});});samples=new CsvIndex(new File(f,"samples.csv"));File ff=new File(f,"frames.csv");if(ff.isFile())frames=new CsvIndex(ff);
   final CsvIndex ready=samples,readyFrames=frames;ui.post(()->{if(destroyed||sessionToken!=sessionGeneration){closeIndex(ready);closeIndex(readyFrames);return;}sampleIndex=ready;frameIndex=readyFrames;summary=result;double sampleEnd=Double.isFinite(ready.lastTime)?ready.lastTime:0,frameEnd=readyFrames!=null&&Double.isFinite(readyFrames.lastTime)?readyFrames.lastTime:0;viewport=new HistoryViewport(Math.max(sampleEnd,frameEnd));if(Double.isFinite(restoredBegin)&&Double.isFinite(restoredEnd)&&restoredEnd>restoredBegin)viewport.set(restoredBegin,restoredEnd);restoredBegin=restoredEnd=Double.NaN;rangeFrom=0;rangeTo=ready.count;renderTab();});
  }catch(Exception e){closeIndex(samples);closeIndex(frames);ui.post(()->{if(!destroyed&&sessionToken==sessionGeneration){content.removeAllViews();note(content,"读取失败："+e.getMessage());content.addView(button("重试读取",()->openSession(f)));}});}});
