 private void updateRangeLabel(){if(rangeLabel!=null&&viewport!=null)rangeLabel.setText("录制经过 "+HistoryTime.elapsed(viewport.begin)+" — "+HistoryTime.elapsed(viewport.end)+"\n"+HistoryTime.clock(summary.optLong("startedUnixMs"),viewport.begin)+" — "+HistoryTime.clock(summary.optLong("startedUnixMs"),viewport.end));}
