 private void selectTime(double t){
  final CsvIndex source=tab==10?frameIndex:sampleIndex;if(source==null||source.count==0){toast("此区间没有原始数据");return;}final CsvIndex sessionSource=sampleIndex;final int token=generation,request=selection.request();final boolean frames=tab==10;final double begin=viewport.begin,end=viewport.end;
  selectionIo.execute(()->{try{int from=source.lowerBound(begin),to=source.upperBound(end);if(from>=to){ui.post(()->{if(current(token,sessionSource))toast("此区间没有采样，请扩大区间");});return;}int index=Math.max(from,Math.min(to-1,source.nearest(t)));String[] values=source.row(index);
   ui.post(()->{if(!current(token,sessionSource)||!selection.current(request))return;if(frames){selectedFrame=index;framePage=(index-from)/50;renderTab();}else if(tab==9){selectedRow=index;selectedSample=values;samplePage=(index-from)/50;renderTab();}else{applySample(source,values,index,t);revealDetails();}});
  }catch(Exception e){ui.post(()->{if(current(token,sessionSource)&&selection.current(request))detailError("时刻读取失败："+e.getMessage());});}});
 }
 private void showSample(int n){
  if(sampleIndex==null||sampleIndex.count==0||detail==null)return;final int requested=Math.max(0,Math.min(sampleIndex.count-1,n)),token=generation,request=selection.request();final CsvIndex source=sampleIndex;final double begin=viewport.begin,end=viewport.end;
  selectionIo.execute(()->{try{int from=source.lowerBound(begin),to=source.upperBound(end);if(from>=to){ui.post(()->{if(current(token,source)&&selection.current(request))detailError("此区间没有原始采样，请扩大范围。");});return;}int index=Math.max(from,Math.min(to-1,requested));String[] values=source.row(index);ui.post(()->{if(current(token,source)&&selection.current(request))applySample(source,values,index,Double.NaN);});}catch(Exception e){ui.post(()->{if(current(token,source)&&selection.current(request))detailError("采样读取失败："+e.getMessage());});}});
 }
 private void applySample(CsvIndex source,String[] values,int index,double requested){
  selectedRow=index;selectedSample=values;double time=CsvIndex.time(values);for(HistoryChart chart:charts)chart.select(time,historyValue(source,values,chart.data.key));if(detail!=null){detail.removeAllViews();sampleDetails(detail,source,values,index);if(Double.isFinite(requested))note(detail,"点选时间 "+HistoryTime.elapsed(requested)+"；显示最近原始行，时间差 "+Numbers.display(Math.abs(time-requested)*1000,3)+" ms。");}
 }
 private void revealDetails(){if(detail!=null&&content!=null&&content.getParent() instanceof ScrollView){final LinearLayout box=detail;content.post(()->{if(box==detail&&content.getParent() instanceof ScrollView)((ScrollView)content.getParent()).smoothScrollTo(0,Math.max(0,box.getTop()-dp(8)));});}}
 private void detailError(String error){if(detail!=null){detail.removeAllViews();note(detail,error);detail.addView(button("重试本次采样",()->showSample(selectedRow>=0?selectedRow:0)));}}
 private double historyValue(CsvIndex source,String[] row,String key){double raw=source.value(row,key);return key.equals("fps")?new FpsSampleValidity(source.header).value(raw,row):raw;}
 private void sampleDetails(LinearLayout box,CsvIndex source,String[] values,int index){
  double time=CsvIndex.time(values);box.addView(text("第 "+(index+1)+" / "+source.count+" 次原始采样 · "+HistoryTime.elapsed(time),14,ACCENT));note(box,HistoryTime.clock(summary.optLong("startedUnixMs"),time));gap(box,4);
  buttons(box,"‹ 上一条",()->showSample(index-1),"下一条 ›",()->showSample(index+1));box.addView(button("全部原始字段 / 精确数值（可复制）",()->rawValues(source,values)));gap(box,6);
  boolean paused=false;int p=source.column("paused");if(p>=0&&p<values.length)paused="true".equalsIgnoreCase(values[p]);if(paused)note(box,"此行处于暂停状态，原始值仍可查看，但不计入区间统计。");
  LinkedHashSet<String> keys=new LinkedHashSet<>(Arrays.asList(Config.METRICS));for(String key:source.header)if(key.matches("cpu[0-9]+MHz"))keys.add(key);
  FpsSampleValidity fpsValidity=new FpsSampleValidity(source.header);for(String key:keys){double v=source.value(values,key);boolean invalidZero=key.equals("fps")&&fpsValidity.invalidZero(v,values);pair(box,Config.label(key),invalidZero?"原始 0（窗口无效）":Config.format(key,v));if(invalidZero)note(box,FpsSampleValidity.reason());else if(!Double.isFinite(v))note(box,HistoryRange.missingReason(source,values,key));}
  for(String key:new String[]{"paused","charging","thermalStatus","frameStatus","frameWindowReady","frameWindowStale","frameDataAgeMs","frameWindowSpanMs","captureGapCount","foregroundPackage","foregroundStatus","frameSourceVerified","gpuLoadStatus","gpuFrequencyStatus","cpuTemperatureStatus","gpuTemperatureStatus","socTemperatureStatus","thermalServiceStatus","thermalServiceSource","frameAvailable","frameProbeCount","frameCandidateCount","frameProbeFailures","layer","longFramesEstimate","bigLongFramesEstimate","unix_ms"}){int i=source.column(key);if(i>=0&&i<values.length&&!values[i].isEmpty())note(box,statusLabel(key)+"："+values[i]);}
 }
 private void rawValues(CsvIndex source,String[] r){StringBuilder s=new StringBuilder();for(int i=0;i<source.header.length;i++){String k=source.header[i];s.append(Config.label(k)).append(" [").append(k).append("]\n").append(i<r.length&&!r[i].isEmpty()?r[i]:"未取得").append(" ").append(Config.unit(k)).append("\n\n");}TextView t=text(s.toString(),13,INK);t.setTextIsSelectable(true);t.setPadding(dp(18),dp(12),dp(18),dp(12));ScrollView sc=new ScrollView(this);sc.addView(t);new AlertDialog.Builder(this).setTitle("原始采样值（可复制）").setView(sc).setPositiveButton("关闭",null).show();}
 private String statusLabel(String s){switch(s){case "paused":return "暂停标记";case "charging":return "充电中";case "thermalStatus":return "系统热状态";case "frameStatus":return "帧来源 / 状态";case "gpuLoadStatus":return "GPU 使用率来源";case "gpuFrequencyStatus":return "GPU 频率来源";case "cpuTemperatureStatus":return "CPU 温度来源";case "gpuTemperatureStatus":return "GPU 温度来源";case "socTemperatureStatus":return "SoC 温度来源";case "thermalServiceStatus":return "系统温度服务状态";case "thermalServiceSource":return "系统温度读数来源";case "frameWindowReady":return "滚动帧窗口已就绪";case "frameDataAgeMs":return "最新呈现帧距今（ms）";case "frameWindowSpanMs":return "滚动窗口跨度（ms）";case "captureGapCount":return "已检测缓冲漏采次数";case "foregroundPackage":return "当时前台应用";case "foregroundStatus":return "前台应用读取状态";case "frameSourceVerified":return "图层归属验证";case "frameAvailable":return "帧接口可用";case "frameProbeCount":return "已尝试图层";case "frameCandidateCount":return "候选图层数";case "frameProbeFailures":return "图层读取失败数";case "layer":return "图层";case "longFramesEstimate":return "累计长帧估算";case "bigLongFramesEstimate":return "累计严重长帧估算";case "unix_ms":return "时间戳（ms）";default:return s;}}
 private void renderRows(boolean frames,int token){
  final CsvIndex source=frames?frameIndex:sampleIndex,sessionSource=sampleIndex;if(source==null||source.count==0){note(content,frames?"此记录没有逐帧数据。未启用帧采集、接口无权限或未返回帧时不会生成有效逐帧行。":"此记录没有完整采样行。");return;}
  final double begin=viewport.begin,end=viewport.end;final int requestedPage=frames?framePage:samplePage,defaultStamp=selection.stamp();final LinearLayout controls=card(content,frames?"逐帧时间 · 原始记录":"采样明细 · 原始记录");note(controls,"正在读取区间内原始数据…");
  final LinearLayout list=card(content,frames?"序号 · 时间 · 呈现间隔":"序号 · 时间 · FPS · CPU · GPU");note(list,"正在加载…");detail=card(content,frames?"本帧详情":"该时刻 · 全部指标");note(detail,"正在加载第一条原始数据…");
  selectionIo.execute(()->{try{int rangeStart=source.lowerBound(begin),rangeEnd=source.upperBound(end),total=rangeEnd-rangeStart;int pageNum=Math.min(Math.max(0,requestedPage),Math.max(0,(total-1)/50)),from=rangeStart+pageNum*50,to=Math.min(rangeEnd,from+50);ArrayList<String[]> rows=new ArrayList<>();source.scan(from,to,(n,row)->rows.add(row));
   ui.post(()->{if(!current(token,sessionSource))return;controls.removeAllViews();list.removeAllViews();if(total==0){note(controls,"此区间没有"+(frames?"逐帧":"采样")+"数据。扩大区间或点“全部”。");detail.removeAllViews();note(detail,"此区间无原始行可显示。");return;}if(frames)framePage=pageNum;else samplePage=pageNum;
    pair(controls,"区间原始行 / 当前页",total+" / "+(pageNum+1)+"—"+((total+49)/50));pair(controls,"原始序号",(from+1)+" — "+to+" / "+source.count);
    buttons(controls,"‹ 上一页",()->{if(frames)framePage=Math.max(0,pageNum-1);else samplePage=Math.max(0,pageNum-1);renderTab();},"下一页 ›",()->{if(frames)framePage=Math.min((total-1)/50,pageNum+1);else samplePage=Math.min((total-1)/50,pageNum+1);renderTab();});
    LinearLayout jump=row();EditText number=new EditText(this);number.setHint("原始序号（区间内）");number.setTextSize(13);number.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);jump.addView(number,new LinearLayout.LayoutParams(0,dp(42),1));jump.addView(button("跳转",()->{try{int n=Integer.parseInt(number.getText().toString())-1;if(n<rangeStart||n>=rangeEnd)throw new IllegalArgumentException();if(frames){framePage=(n-rangeStart)/50;selectedFrame=n;}else{samplePage=(n-rangeStart)/50;selectedRow=n;}renderTab();}catch(Exception e){number.setError("请输入 "+(rangeStart+1)+" — "+rangeEnd+" 的原始序号");}}));controls.addView(jump);
    note(controls,frames?"间隔来自实际呈现时间。未返回的帧无法补回；空值不填零。":"每一行来自原始 CSV，区间内全量可翻页。点行显示所有指标及读取原因。");
    for(int x=0;x<rows.size();x++){final int index=from+x;final String[] values=rows.get(x);String label=String.format(Locale.US,"#%d   %s   ",index+1,Config.elapsed(CsvIndex.time(values)));label+=frames?Numbers.display(source.value(values,"interval_ms"),3)+" ms":Numbers.display(source.value(values,"fps"),1)+"   "+Numbers.display(source.value(values,"cpuPct"),1)+"%   "+Numbers.display(source.value(values,"gpuPct"),1)+"%";
     TextView row=text(label,12,INK);row.setPadding(0,dp(11),0,dp(11));row.setBackground(round(index==(frames?selectedFrame:selectedRow)?0xFFD6D5EC:CARD,3));row.setOnClickListener(v->{selection.request();if(frames)applyFrame(source,values,index);else applySample(source,values,index,Double.NaN);revealDetails();});list.addView(row);View line=new View(this);line.setBackgroundColor(0xFFD3D0E1);list.addView(line,new LinearLayout.LayoutParams(-1,dp(1)));
    }
    int selected=frames?selectedFrame:selectedRow;int index=selected>=from&&selected<to?selected:from;if(selection.current(defaultStamp)){if(frames)applyFrame(source,rows.get(index-from),index);else applySample(source,rows.get(index-from),index,Double.NaN);}
   });
  }catch(Exception e){ui.post(()->{if(current(token,sessionSource)){controls.removeAllViews();note(controls,"读取失败："+e.getMessage());list.removeAllViews();note(list,"可刷新记录快照后重试。");detailError("无法读取原始数据："+e.getMessage());}});}});
 }
 private void showFrame(int n){
  final CsvIndex source=frameIndex,sessionSource=sampleIndex;if(source==null||source.count==0||detail==null)return;final int requested=Math.max(0,Math.min(source.count-1,n)),token=generation,request=selection.request();final double begin=viewport.begin,end=viewport.end;
  selectionIo.execute(()->{try{int from=source.lowerBound(begin),to=source.upperBound(end);if(from>=to){ui.post(()->{if(current(token,sessionSource)&&selection.current(request))detailError("此区间没有原始逐帧数据。");});return;}int index=Math.max(from,Math.min(to-1,requested));String[] values=source.row(index);ui.post(()->{if(current(token,sessionSource)&&selection.current(request))applyFrame(source,values,index);});}catch(Exception e){ui.post(()->{if(current(token,sessionSource)&&selection.current(request))detailError("逐帧读取失败："+e.getMessage());});}});
 }
 private void applyFrame(CsvIndex source,String[] values,int index){
  selectedFrame=index;if(detail==null)return;detail.removeAllViews();double time=CsvIndex.time(values),interval=source.value(values,"interval_ms");detail.addView(text("第 "+(index+1)+" / "+source.count+" 条呈现间隔 · "+HistoryTime.elapsed(time),14,ACCENT));note(detail,HistoryTime.clock(summary.optLong("startedUnixMs"),time));buttons(detail,"‹ 上一帧",()->showFrame(index-1),"下一帧 ›",()->showFrame(index+1));pair(detail,"帧间隔",Numbers.display(interval,6)+" ms");pair(detail,"瞬时帧率（间隔倒数）",Numbers.display(interval>0?1000/interval:Double.NaN,6)+" fps");detail.addView(button("查看全部原始字段",()->rawValues(source,values)));for(int i=0;i<source.header.length&&i<values.length;i++)note(detail,source.header[i]+"："+(values[i].isEmpty()?"未取得":values[i]));
 }
 private void sessionMenu(){new AlertDialog.Builder(this).setItems(new String[]{"刷新当前记录快照","删除记录"},(d,n)->{if(n==0)openSession(session);else{if(MonitorService.running&&session.getAbsolutePath().equals(MonitorService.sessionPath)){toast("请先停止正在记录的会话");return;}new AlertDialog.Builder(this).setTitle("删除此记录？").setMessage("这会删除该记录的全部原始数据。").setNegativeButton("取消",null).setPositiveButton("删除",(dialog,which)->{File f=session;generation++;io.execute(()->{closeIndexes();boolean ok=deleteTree(f);ui.post(()->{toast(ok?"已删除":"删除失败");showRecords();});});}).show();}}).show();}
 private boolean deleteTree(File f){File[] a=f.listFiles();if(a!=null)for(File child:a)if(!deleteTree(child))return false;return f.delete();}
 private void exportMenu(){if(session==null)return;new AlertDialog.Builder(this).setTitle("导出").setItems(new String[]{"全部数据 ZIP","全部采样 CSV","全部逐帧 CSV","当前区间采样 CSV","当前区间逐帧 CSV","当前曲线 PNG"},(d,n)->{if(n==1)exportFile(new File(session,"samples.csv"));else if(n==2)exportFile(new File(session,"frames.csv"));else if(n==3||n==4)exportRange(n==4);else if(n==5){if(charts.isEmpty()){toast("先打开一个指标曲线");return;}if(rangeStats==null){toast("正在更新区间曲线，请稍后导出");return;}String[] labels=new String[charts.size()];for(int i=0;i<labels.length;i++)labels[i]=Config.label(charts.get(i).data.key);new AlertDialog.Builder(this).setTitle("选择曲线").setItems(labels,(dialog,x)->makeImage(charts.get(x))).show();}else makeZip();}).show();}
 private void exportRange(boolean frames){
  final CsvIndex source=frames?frameIndex:sampleIndex;if(source==null){toast("此记录未保存逐帧数据");return;}final double begin=viewport.begin,end=viewport.end;final File folder=session;toast("正在导出此区间的全部原始数值…");io.execute(()->{try{File dest=new File(getCacheDir(),"exports");dest.mkdirs();File out=new File(dest,folder.getName()+"_"+(frames?"frames":"samples")+"_"+Math.round(begin*1000)+"-"+Math.round(end*1000)+"ms.csv");try(Writer writer=new BufferedWriter(new OutputStreamWriter(new FileOutputStream(out),StandardCharsets.UTF_8))){writer.write(CsvIndex.encode(source.header)+"\n");source.scan(source.lowerBound(begin),source.upperBound(end),(n,row)->{try{writer.write(CsvIndex.encode(row)+"\n");}catch(IOException e){throw new UncheckedIOException(e);}});}ui.post(()->exportFile(out));}catch(Exception e){ui.post(()->toast("区间导出失败："+e.getMessage()));}});
 }
 private void makeZip(){File src=session;toast("正在打包完整记录…");io.execute(()->{try{File dest=new File(getCacheDir(),"exports");dest.mkdirs();File zip=new File(dest,src.getName()+".zip");try(ZipOutputStream out=new ZipOutputStream(new BufferedOutputStream(new FileOutputStream(zip)))){File[] files=src.listFiles(File::isFile);if(files!=null)for(File f:files)if(!f.getName().endsWith(".tmp")){out.putNextEntry(new ZipEntry(f.getName()));try(InputStream in=new FileInputStream(f)){byte[] b=new byte[32768];for(int n;(n=in.read(b))!=-1;)out.write(b,0,n);}out.closeEntry();}}ui.post(()->exportFile(zip));}catch(Exception e){ui.post(()->toast(e.toString()));}});}
 private int adaptiveChartHeight(HistoryChart chart){
  int windowWidth=historyBody!=null&&historyBody.getWidth()>0?historyBody.getWidth():root.getWidth()-root.getPaddingLeft()-root.getPaddingRight();int width=chart.getWidth()>0?chart.getWidth():Math.max(dp(160),windowWidth-dp(24));int height=historyBody!=null?historyBody.getHeight():body.getHeight();return chart.recommendedHeight(width,height);
 }
 private void updateChartHeights(){if(destroyed||!page.equals("session"))return;for(HistoryChart chart:charts){android.view.ViewGroup.LayoutParams lp=chart.getLayoutParams();if(lp!=null){int height=adaptiveChartHeight(chart);if(lp.height!=height){lp.height=height;chart.setLayoutParams(lp);}chart.invalidate();}}}
 private void imageText(Canvas c,android.text.TextPaint paint,String s,float x,float y,int maxWidth){String fit=android.text.TextUtils.ellipsize(s,paint,maxWidth,android.text.TextUtils.TruncateAt.END).toString();c.drawText(fit,x,y,paint);}
 private void makeImage(HistoryChart chart){
  File dest=new File(getCacheDir(),"exports");dest.mkdirs();File out=new File(dest,session.getName()+"_"+chart.data.key+".png");int width=1200,margin=28,headerHeight=118,chartWidth=width-2*margin,chartHeight=chart.recommendedHeight(chartWidth,900,2f,2f),height=headerHeight+chartHeight+104;
  Bitmap image=Bitmap.createBitmap(width,height,Bitmap.Config.ARGB_8888);try{Canvas c=new Canvas(image);c.drawColor(BG);android.text.TextPaint p=new android.text.TextPaint(Paint.ANTI_ALIAS_FLAG);p.setColor(INK);p.setTextSize(30);imageText(c,p,summary.optString("title","轻帧记录"),margin,42,chartWidth);p.setTextSize(20);p.setColor(MUTED);imageText(c,p,summary.optString("device","")+" · "+summary.optString("backend","")+" · "+sampleIndex.count+" 次原始采样",margin,74,chartWidth);imageText(c,p,"录制经过 "+HistoryTime.elapsed(chart.viewport.begin)+" — "+HistoryTime.elapsed(chart.viewport.end),margin,101,chartWidth);
   c.save();c.translate(margin,headerHeight);chart.render(c,chartWidth,chartHeight,2f,2f);c.restore();p.setTextSize(19);imageText(c,p,"轻帧 "+Config.VERSION+" · 数字纵轴 / 原始单位 · 区间统计使用全部有效原始样本",margin,headerHeight+chartHeight+36,chartWidth);imageText(c,p,"空值不填零；曲线合并绘制；点选的精确数值及全部原始记录保存在 CSV",margin,headerHeight+chartHeight+65,chartWidth);
   try(OutputStream stream=new FileOutputStream(out)){image.compress(Bitmap.CompressFormat.PNG,100,stream);}exportFile(out);
  }catch(Exception e){toast(e.toString());}finally{image.recycle();}
 }
 private String mime(File f){return f.getName().endsWith(".csv")?"text/csv":f.getName().endsWith(".png")?"image/png":f.getName().endsWith(".txt")?"text/plain":"application/zip";}
 private void exportFile(File f){if(!f.isFile()){toast("文件尚未生成");return;}new AlertDialog.Builder(this).setTitle(f.getName()).setItems(new String[]{"保存到文件","分享"},(d,n)->{try{if(n==0){pendingExport=f;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType(mime(f));i.putExtra(Intent.EXTRA_TITLE,f.getName());startActivityForResult(i,201);}else{Uri uri=ExportProvider.uri(this,f);Intent i=new Intent(Intent.ACTION_SEND);i.setType(mime(f));i.putExtra(Intent.EXTRA_STREAM,uri);i.setClipData(ClipData.newRawUri(f.getName(),uri));i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(Intent.createChooser(i,"分享记录"));}}catch(Exception e){toast(e.toString());}}).show();}
 @Override protected void onActivityResult(int code,int result,Intent data){super.onActivityResult(code,result,data);if(code==201&&result==RESULT_OK&&data!=null&&data.getData()!=null&&pendingExport!=null){Uri uri=data.getData();File src=pendingExport;pendingExport=null;io.execute(()->{try(InputStream in=new FileInputStream(src);OutputStream out=getContentResolver().openOutputStream(uri)){if(out==null)throw new IOException("无法打开目标文件");byte[] b=new byte[32768];for(int n;(n=in.read(b))!=-1;)out.write(b,0,n);ui.post(()->toast("已保存"));}catch(Exception e){ui.post(()->toast("保存失败："+e));}});}}
 @Override public void onBackPressed(){if(page.equals("session"))showRecords();else if(!page.equals("home"))showHome();else super.onBackPressed();}
 private void toast(String s){if(!destroyed)Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
